
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_sogga_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_sogga", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.243299070701411e+00, -4.160617162107918e+00, -4.044823171109501e+00, -3.884553881705604e+00, -3.666453410376801e+00, -3.376798302501910e+00, -3.005339600369407e+00, -2.552279950116981e+00, -2.037811711480075e+00, -1.507217374803044e+00, -1.013450118444241e+00, -6.937828773397015e-01, -5.966133765914233e-01, -4.890056216824211e-01, -3.521400770557175e-01, -2.234040787477752e-01, -1.204022180568158e-01, -4.300667032962913e-02, -9.305829235310301e-03, -1.046317516824520e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


